package com.cookyou.app;
import android.app.Activity;import android.os.Bundle;import android.webkit.*;import android.graphics.Color;import android.view.View;
public class MainActivity extends Activity {
 private WebView web;
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().setStatusBarColor(Color.rgb(251,248,241));getWindow().setNavigationBarColor(Color.rgb(251,248,241));getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);web=new WebView(this);web.setBackgroundColor(Color.rgb(251,248,241));web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest req){if(req.getUrl().toString().equals("https://app.cookyou.local/")){try{return new WebResourceResponse("text/html","UTF-8",getAssets().open("index.html"));}catch(Exception e){throw new RuntimeException(e);}}return new WebResourceResponse("text/plain","UTF-8",new java.io.ByteArrayInputStream(new byte[0]));}@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}});setContentView(web);web.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});web.loadUrl("https://app.cookyou.local/");}
 @Override public void onBackPressed(){web.evaluateJavascript("window.cookyouBack ? window.cookyouBack() : false",value->{if(!"true".equals(value))finish();});}
 @Override protected void onDestroy(){web.destroy();super.onDestroy();}
}